insert into public.lessons (slug,band,grade,semester,subject,topic,title,hero_image,content,sort_order) values ('m4-01','3~4',4,1,'수학','큰 수','만보다 큰 수는 어떻게 읽고 쓸까?','assets/img/l_m4-01.jpg',$j${"intro": "신문에서 '관객 1250만 명', '나라 살림 600조 원' 같은 말을 본 적 있나요? 9999보다 더 큰 수를 읽고 쓰는 방법을 알면 세상의 큰 숫자들이 한눈에 들어와요.", "sections": [{"heading": "1000이 10개면 10000, 만이에요", "paras": ["9999보다 1 큰 수를 10000이라고 써요. 읽을 때는 '만' 또는 '일만'이라고 해요.", "10000은 1000이 10개, 100이 100개, 10이 1000개 모인 수예요. 그래서 9000보다 1000 큰 수, 9990보다 10 큰 수도 모두 10000이에요."], "example": "1000원짜리 지폐 10장 = 10000원 = 만 원", "figure": "천 원짜리 지폐 10장을 한 줄로 늘어놓고 옆에 만 원짜리 지폐 한 장을 놓은 모습"}, {"heading": "다섯 자리 수의 자릿값", "paras": ["10000이 3개, 1000이 5개, 100이 2개, 10이 7개, 1이 4개인 수는 35274예요. 맨 앞자리부터 만의 자리, 천의 자리, 백의 자리, 십의 자리, 일의 자리라고 해요.", "같은 숫자라도 어느 자리에 있느냐에 따라 나타내는 값이 달라요. 35274에서 3은 30000을, 7은 70을 나타내요.", "읽을 때는 앞에서부터 숫자와 자리 이름을 함께 읽어요. 숫자가 0인 자리는 읽지 않고, 숫자가 1이면 '일'을 빼고 자리 이름만 읽어요."], "example": "35274 = 30000 + 5000 + 200 + 70 + 4 → 삼만 오천이백칠십사 / 40508 → 사만 오백팔", "figure": "만, 천, 백, 십, 일 칸이 그려진 자릿값 표에 숫자 카드 3, 5, 2, 7, 4를 하나씩 넣은 모습"}, {"heading": "십만, 백만, 천만, 그리고 억과 조", "paras": ["10000이 10개면 십만(100000), 100개면 백만(1000000), 1000개면 천만(10000000)이에요.", "천만이 10개면 1억(100000000)이에요. 1억은 0이 8개나 붙어요. 천억이 10개면 1조로, 0이 12개예요.", "큰 수는 일의 자리부터 네 자리씩 끊으면 쉽게 읽을 수 있어요. 끊은 곳마다 '만', '억', '조'를 붙여 읽어요."], "example": "520340000 → 5|2034|0000 → 5억 2034만 → 오억 이천삼십사만", "figure": "긴 숫자 띠 위에 네 자리마다 연필로 세로 금을 긋고 그 위에 만, 억, 조라고 적은 모습"}, {"heading": "뛰어 세기로 수의 순서 알기", "paras": ["10000씩 뛰어 세면 만의 자리 숫자가 1씩 커져요. 10만씩 뛰어 세면 십만의 자리 숫자가 1씩 커지고요.", "어느 자리 숫자가 바뀌는지 살펴보면 얼마씩 뛰어 세었는지 알 수 있어요. 9 다음에는 윗자리로 1이 올라가는 것도 잊지 마세요."], "example": "25000 - 35000 - 45000 - 55000 (만의 자리가 1씩 커져요 → 10000씩) / 1억 9000만 - 2억 - 2억 1000만 (1000만씩)", "figure": "수직선 위에 같은 간격으로 화살표를 그리며 25000, 35000, 45000을 적은 공책"}, {"heading": "이렇게 풀어요: 큰 수의 크기 비교", "paras": ["먼저 두 수의 자리 수를 세어 봐요. 자리 수가 많은 수가 더 커요.", "자리 수가 같으면 가장 높은 자리 숫자부터 차례로 비교해요. 처음으로 다른 숫자가 나온 자리에서 숫자가 큰 쪽이 더 큰 수예요."], "example": "① 382540(여섯 자리)과 98960(다섯 자리) → 382540 > 98960 ② 572031과 571999 → 십만, 만의 자리는 같고 천의 자리 2 > 1 → 572031 > 571999", "figure": "두 수를 위아래로 자리 맞춰 쓰고, 처음으로 다른 숫자에 동그라미를 친 모습"}], "keywords": [{"word": "만", "meaning": "1000이 10개인 수, 10000"}, {"word": "자릿값", "meaning": "숫자가 놓인 자리에 따라 나타내는 값"}, {"word": "억", "meaning": "천만이 10개인 수, 100000000"}, {"word": "조", "meaning": "천억이 10개인 수, 0이 12개 붙은 수"}, {"word": "뛰어 세기", "meaning": "일정한 크기만큼 계속 더해 가며 세는 것"}], "expressions": [], "quiz": [{"q": "10000에 대한 설명으로 __틀린__ 것은 무엇일까요?", "choices": ["1000이 10개인 수", "9999보다 1 큰 수", "100이 10개인 수", "9000보다 1000 큰 수"], "answer": 2, "explain": "100이 10개면 1000이에요. 10000은 100이 100개인 수예요."}, {"q": "47053을 바르게 읽은 것은 무엇일까요?", "choices": ["사만 칠천영백오십삼", "사만 칠천오십삼", "사천칠백오십삼", "사만 칠천오백삼"], "answer": 1, "explain": "0인 백의 자리는 읽지 않아요. 사만 칠천오십삼이에요."}, {"q": "'삼백오십만'을 숫자로 바르게 쓴 것은 무엇일까요?", "choices": ["3500000", "350000", "35000000", "3050000"], "answer": 0, "explain": "삼백오십만은 350만이에요. 350 뒤에 만을 뜻하는 0 네 개를 붙이면 3500000이에요."}, {"q": "1억은 천만이 몇 개인 수일까요?", "choices": ["100개", "1000개", "1개", "10개"], "answer": 3, "explain": "천만이 10개면 1억이에요."}, {"q": "다음 중 가장 큰 수는 무엇일까요?", "choices": ["989999", "1000100", "999990", "1000010"], "answer": 1, "explain": "일곱 자리 수 두 개 중에서 백의 자리가 1인 1000100이 십의 자리가 1인 1000010보다 커요."}], "summary": ["1000이 10개면 10000(만), 천만이 10개면 1억, 천억이 10개면 1조예요.", "큰 수는 일의 자리부터 네 자리씩 끊어 만, 억, 조를 붙여 읽어요.", "크기 비교는 자리 수를 먼저 보고, 같으면 높은 자리부터 비교해요."], "parent_tip": "아이들은 0이 있는 수를 읽고 쓸 때(예: 사만 오백팔 → 40508) 가장 많이 실수합니다. 일의 자리부터 네 자리씩 끊는 습관을 들이고, 뉴스나 마트 가격표에서 큰 수를 찾아 함께 읽어 보세요. '1억은 만 원짜리가 몇 장일까?'처럼 물어보면 수의 크기를 느끼는 데 도움이 됩니다."}$j$::jsonb,400) on conflict (slug) do update set grade=4,semester=excluded.semester,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,grade,semester,subject,name,sort_order,lesson_slug) select '3~4',4,1,'수학','큰 수',400,'m4-01' where not exists (select 1 from public.topics where lesson_slug='m4-01');
insert into public.lessons (slug,band,grade,semester,subject,topic,title,hero_image,content,sort_order) values ('m4-02','3~4',4,1,'수학','각도','각의 크기는 어떻게 잴까?','assets/img/l_m4-02.jpg',$j${"intro": "문을 조금 열 때와 활짝 열 때, 벌어진 정도가 다르지요? 각이 얼마나 벌어졌는지를 숫자로 나타내는 방법을 배워 봐요.", "sections": [{"heading": "각의 크기와 1도", "paras": ["각의 두 변이 벌어진 정도를 각의 크기 또는 각도라고 해요. 변의 길이가 길다고 각이 커지는 게 아니라, 많이 벌어질수록 커요.", "직각을 똑같이 90으로 나눈 것 하나의 크기를 1도라고 하고 1°라고 써요. 그래서 직각은 90°예요.", "직각 두 개를 이어 붙여 한 직선이 되면 180°, 직각 네 개면 한 바퀴로 360°예요."], "example": "직각 = 90°, 직각 2개 = 90° + 90° = 180°", "figure": "부채를 조금 편 모습과 활짝 편 모습을 나란히 놓고 벌어진 정도를 비교하는 사진"}, {"heading": "이렇게 재요: 각도기 사용법", "paras": ["① 각도기의 중심을 각의 꼭짓점에 맞춰요. ② 각도기의 밑금을 각의 한 변에 맞춰요. ③ 나머지 변이 가리키는 눈금을 읽어요.", "각도기에는 안쪽과 바깥쪽 두 줄의 눈금이 있어요. 밑금에 맞춘 변 쪽에서 0부터 시작하는 눈금을 따라 읽어야 해요.", "각을 그릴 때는 먼저 한 변을 긋고, 각도기 중심과 밑금을 맞춘 뒤 원하는 눈금에 점을 찍어 꼭짓점과 이어요."], "example": "한 변이 오른쪽 0에서 시작하고 다른 변이 안쪽 눈금 65를 가리키면 → 65°", "figure": "아이 손이 반원 모양 각도기의 중심을 종이에 그린 각의 꼭짓점에 맞추는 모습"}, {"heading": "예각과 둔각, 그리고 어림하기", "paras": ["0°보다 크고 직각보다 작은 각을 예각, 직각보다 크고 180°보다 작은 각을 둔각이라고 해요.", "각도기를 쓰기 전에 직각(90°)과 비교해서 크기를 먼저 어림해 보세요. 예각인데 눈금이 130이 나왔다면 다른 쪽 눈금을 읽은 거예요.", "눈금에 꼭 맞지 않으면 '약 몇 도'라고 말해요."], "example": "40° → 예각, 90° → 직각, 125° → 둔각", "figure": "종이 직각 삼각자를 기준으로 좁은 각과 넓은 각을 비교해 보는 아이 손"}, {"heading": "각도의 합과 차", "paras": ["각도도 자연수처럼 더하고 뺄 수 있어요. 두 각을 붙이면 합, 큰 각에서 작은 각을 떼어 내면 차예요.", "계산한 뒤에는 단위 °를 꼭 붙여요."], "example": "75° + 40° = 115°, 150° − 65° = 85° / 직선(180°)에서 한 각이 70°이면 나머지는 180° − 70° = 110°", "figure": "종이 부채꼴 조각 두 개를 꼭짓점을 맞춰 이어 붙인 모습"}, {"heading": "이렇게 알아내요: 삼각형과 사각형의 각의 합", "paras": ["삼각형을 종이로 오려 세 꼭짓점을 찢어 한 점에 모아 보면 한 직선이 돼요. 그래서 삼각형의 세 각의 크기의 합은 180°예요.", "사각형은 마주 보는 두 꼭짓점을 선분으로 이으면 삼각형 2개로 나뉘어요. 그래서 네 각의 크기의 합은 180° + 180° = 360°예요.", "모르는 한 각은 전체 합에서 아는 각들을 빼서 구해요."], "example": "삼각형의 두 각이 50°, 75°이면 나머지 = 180° − 50° − 75° = 55° / 사각형의 세 각이 80°, 100°, 95°이면 나머지 = 360° − 275° = 85°", "figure": "색종이 삼각형의 세 귀퉁이를 찢어 한 점에 모아 반원 모양으로 붙인 모습"}], "keywords": [{"word": "각도", "meaning": "각의 두 변이 벌어진 정도, 각의 크기"}, {"word": "1도(1°)", "meaning": "직각을 똑같이 90으로 나눈 것 하나의 크기"}, {"word": "각도기", "meaning": "각의 크기를 재는 도구"}, {"word": "예각", "meaning": "0°보다 크고 직각보다 작은 각"}, {"word": "둔각", "meaning": "직각보다 크고 180°보다 작은 각"}], "expressions": [], "quiz": [{"q": "직각의 크기는 몇 도일까요?", "choices": ["45°", "180°", "90°", "100°"], "answer": 2, "explain": "직각을 90으로 똑같이 나눈 하나가 1°이므로 직각은 90°예요."}, {"q": "각도기로 각을 잴 때 각도기의 중심은 어디에 맞출까요?", "choices": ["각의 꼭짓점", "변의 끝", "종이 모서리", "아무 곳이나"], "answer": 0, "explain": "각도기의 중심은 각의 꼭짓점에, 밑금은 각의 한 변에 맞춰요."}, {"q": "다음 중 둔각은 무엇일까요?", "choices": ["35°", "90°", "89°", "135°"], "answer": 3, "explain": "둔각은 직각(90°)보다 크고 180°보다 작은 각이에요. 135°가 둔각이에요."}, {"q": "삼각형의 두 각이 65°, 45°일 때 나머지 한 각은 몇 도일까요?", "choices": ["80°", "70°", "110°", "60°"], "answer": 1, "explain": "180° − 65° − 45° = 70°예요."}, {"q": "사각형의 네 각의 크기의 합은 몇 도일까요?", "choices": ["180°", "270°", "360°", "400°"], "answer": 2, "explain": "사각형은 삼각형 2개로 나눌 수 있으니 180° + 180° = 360°예요."}], "summary": ["직각을 90으로 똑같이 나눈 하나가 1°이고, 각도기로 각의 크기를 재요.", "예각은 직각보다 작은 각, 둔각은 직각보다 크고 180°보다 작은 각이에요.", "삼각형의 세 각의 합은 180°, 사각형의 네 각의 합은 360°예요."], "parent_tip": "각도기를 쓸 때 안쪽과 바깥쪽 눈금을 바꿔 읽어 40°를 140°로 답하는 실수가 가장 흔합니다. 재기 전에 '직각보다 클까, 작을까?'를 먼저 물어 어림하게 해 주세요. 시계 바늘, 문 열림, 노트북 화면처럼 집 안의 각을 함께 재 보면 양감이 좋아집니다."}$j$::jsonb,401) on conflict (slug) do update set grade=4,semester=excluded.semester,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,grade,semester,subject,name,sort_order,lesson_slug) select '3~4',4,1,'수학','각도',401,'m4-02' where not exists (select 1 from public.topics where lesson_slug='m4-02');
insert into public.lessons (slug,band,grade,semester,subject,topic,title,hero_image,content,sort_order) values ('m4-03','3~4',4,1,'수학','곱셈과 나눗셈','큰 수의 곱셈과 나눗셈, 어떻게 할까?','assets/img/l_m4-03.jpg',$j${"intro": "한 상자에 254개씩 든 구슬이 36상자 있다면 구슬은 모두 몇 개일까요? 큰 수도 자리를 나누어 차근차근 곱하고 나누면 쉽게 구할 수 있어요.", "sections": [{"heading": "(몇백)×(몇십)은 0의 개수를 세어요", "paras": ["300 × 40은 3 × 4 = 12를 먼저 계산해요.", "그다음 곱하는 두 수의 0을 모두 세어 12 뒤에 붙여요. 300에 0이 2개, 40에 0이 1개이니 모두 3개를 붙이면 12000이에요."], "example": "300 × 40 → 3 × 4 = 12 → 0을 3개 붙여요 → 12000", "figure": "100원짜리 동전 3개씩 놓인 묶음이 40줄로 늘어선 모습"}, {"heading": "이렇게 풀어요: (세 자리 수)×(두 자리 수)", "paras": ["곱하는 수 36을 30과 6으로 나누어 생각해요. 254 × 6과 254 × 30을 따로 구해서 더하면 돼요.", "세로셈으로 쓸 때 254 × 3을 계산한 값은 십의 자리부터 맞추어 써요. 사실은 254 × 30이라 일의 자리 0을 생략한 거예요."], "example": "254 × 36 ① 254 × 6 = 1524 ② 254 × 30 = 7620 ③ 1524 + 7620 = 9144", "figure": "공책에 세로셈 254 × 36을 쓰고 두 줄의 부분 곱을 자리 맞추어 적은 모습"}, {"heading": "나누는 수가 두 자리 수인 나눗셈", "paras": ["80 ÷ 20은 '20이 80 안에 몇 번 들어갈까?'를 생각해요. 20 × 4 = 80이니 몫은 4예요.", "75 ÷ 23처럼 똑 떨어지지 않으면 남는 수가 생겨요. 23 × 3 = 69이고 75 − 69 = 6이 남아요. 이때 3이 몫, 6이 나머지예요.", "나머지는 항상 나누는 수보다 작아야 해요. 나머지가 나누는 수보다 크거나 같으면 몫을 1 더 크게 해야 해요."], "example": "75 ÷ 23 = 3 … 6 (23 × 3 = 69, 75 − 69 = 6)", "figure": "사탕 75개를 23개씩 봉지에 담고 남은 6개를 따로 놓은 모습"}, {"heading": "이렇게 풀어요: (세 자리 수)÷(두 자리 수)", "paras": ["586 ÷ 24에서 먼저 58 안에 24가 몇 번 들어가는지 봐요. 24 × 2 = 48이므로 몫의 십의 자리에 2를 써요.", "58 − 48 = 10을 쓰고 일의 자리 6을 내려 106을 만들어요. 24 × 4 = 96이므로 몫의 일의 자리에 4를 쓰고 106 − 96 = 10이 남아요.", "계산이 맞는지 확인할 때는 나누는 수와 몫을 곱하고 나머지를 더해 봐요. 처음 수가 나오면 맞게 푼 거예요. 이것을 검산이라고 해요."], "example": "586 ÷ 24 = 24 … 10 / 검산: 24 × 24 = 576, 576 + 10 = 586", "figure": "나눗셈 세로셈에서 내려 쓰는 숫자 옆에 연필로 화살표를 그린 공책"}, {"heading": "어림셈으로 답을 미리 짐작해요", "paras": ["398 × 21은 398을 약 400으로, 21을 약 20으로 생각하면 400 × 20 = 8000쯤이에요.", "정확히 계산하면 8358이에요. 어림한 값과 크게 다르지 않으니 계산이 그럴듯하다고 확인할 수 있어요.", "나눗셈도 마찬가지예요. 612 ÷ 29는 600 ÷ 30 = 20쯤이라고 어림하면 몫이 두 자리 수라는 걸 알 수 있어요."], "example": "398 × 21 → 약 400 × 20 = 8000 / 실제 값 8358", "figure": "마트 장바구니 속 물건 가격표 옆에 어림한 금액을 메모지에 적는 아이 손"}], "keywords": [{"word": "몫", "meaning": "나눗셈에서 나누는 수가 몇 번 들어가는지 나타내는 수"}, {"word": "나머지", "meaning": "나누고 남은 수. 항상 나누는 수보다 작아요"}, {"word": "나누어떨어진다", "meaning": "나머지가 0인 것"}, {"word": "검산", "meaning": "계산이 맞는지 다시 확인하는 것"}, {"word": "어림셈", "meaning": "수를 간단하게 만들어 대강의 값을 구하는 계산"}], "expressions": [], "quiz": [{"q": "500 × 60은 얼마일까요?", "choices": ["3000", "300000", "30000", "3600"], "answer": 2, "explain": "5 × 6 = 30이고 0이 3개 더 붙으니 30000이에요."}, {"q": "312 × 23은 얼마일까요?", "choices": ["7176", "1560", "6240", "7276"], "answer": 0, "explain": "312 × 3 = 936, 312 × 20 = 6240, 936 + 6240 = 7176이에요."}, {"q": "96 ÷ 18의 몫과 나머지를 바르게 나타낸 것은 무엇일까요?", "choices": ["몫 4, 나머지 24", "몫 6, 나머지 0", "몫 5, 나머지 8", "몫 5, 나머지 6"], "answer": 3, "explain": "18 × 5 = 90이고 96 − 90 = 6이에요. 몫은 5, 나머지는 6이에요."}, {"q": "어떤 나눗셈의 나누는 수가 27일 때 나머지가 될 수 없는 수는 무엇일까요?", "choices": ["0", "27", "26", "15"], "answer": 1, "explain": "나머지는 나누는 수 27보다 작아야 해요. 27은 나머지가 될 수 없어요."}, {"q": "503 × 19를 어림한 값으로 가장 알맞은 것은 무엇일까요?", "choices": ["1000", "100000", "10000", "500"], "answer": 2, "explain": "503은 약 500, 19는 약 20이니 500 × 20 = 10000쯤이에요."}], "summary": ["(몇백)×(몇십)은 앞의 수끼리 곱하고 0의 개수만큼 0을 붙여요.", "(세 자리 수)×(두 자리 수)는 곱하는 수를 몇십과 몇으로 나누어 곱한 뒤 더해요.", "나눗셈의 나머지는 나누는 수보다 작고, 나누는 수 × 몫 + 나머지로 검산해요."], "parent_tip": "곱셈에서는 십의 자리 부분 곱을 한 칸 왼쪽으로 맞추지 않는 실수, 나눗셈에서는 몫을 너무 작게 잡아 나머지가 나누는 수보다 커지는 실수가 많습니다. 계산 전에 '대략 얼마쯤일까?'를 먼저 말하게 하고, 나눗셈 뒤에는 검산을 습관으로 들여 주세요."}$j$::jsonb,402) on conflict (slug) do update set grade=4,semester=excluded.semester,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,grade,semester,subject,name,sort_order,lesson_slug) select '3~4',4,1,'수학','곱셈과 나눗셈',402,'m4-03' where not exists (select 1 from public.topics where lesson_slug='m4-03');
insert into public.lessons (slug,band,grade,semester,subject,topic,title,hero_image,content,sort_order) values ('m4-04','3~4',4,1,'수학','삼각형','삼각형은 어떻게 나눌 수 있을까?','assets/img/l_m4-04.jpg',$j${"intro": "옷걸이, 샌드위치, 지붕 모양처럼 주변에는 여러 가지 삼각형이 있어요. 변의 길이와 각의 크기를 살펴보면 삼각형을 이름 붙여 나눌 수 있어요.", "sections": [{"heading": "변의 길이로 나누기: 이등변삼각형과 정삼각형", "paras": ["두 변의 길이가 같은 삼각형을 이등변삼각형이라고 해요.", "세 변의 길이가 모두 같은 삼각형은 정삼각형이에요. 정삼각형도 두 변의 길이가 같으니까 이등변삼각형이라고 할 수 있어요.", "세 변의 길이가 모두 다르면 이등변삼각형도, 정삼각형도 아니에요."], "example": "변의 길이 5cm, 5cm, 3cm → 이등변삼각형 / 4cm, 4cm, 4cm → 정삼각형(이등변삼각형이기도 해요)", "figure": "빨대를 잘라 만든 삼각형 세 개(두 변이 같은 것, 세 변이 같은 것, 모두 다른 것)를 책상에 놓은 모습"}, {"heading": "이등변삼각형은 두 각의 크기가 같아요", "paras": ["종이로 이등변삼각형을 오려 길이가 같은 두 변이 겹치도록 반으로 접어 보세요. 아래의 두 각이 꼭 맞게 포개져요.", "그래서 이등변삼각형은 길이가 같은 두 변과 만나는 밑의 두 각의 크기가 같아요.", "삼각형의 세 각의 합이 180°라는 것을 함께 쓰면 모르는 각을 구할 수 있어요."], "example": "이등변삼각형에서 길이가 같은 두 변 사이의 각이 40°이면 나머지 두 각은 (180° − 40°) ÷ 2 = 70°씩", "figure": "종이 이등변삼각형을 반으로 접어 밑의 두 각이 겹쳐지는 모습"}, {"heading": "정삼각형은 세 각이 모두 60°예요", "paras": ["정삼각형은 어느 변끼리 접어도 꼭 맞게 겹쳐요. 그래서 세 각의 크기가 모두 같아요.", "세 각의 합이 180°이므로 한 각은 180° ÷ 3 = 60°예요."], "example": "정삼각형의 한 각 = 180° ÷ 3 = 60°", "figure": "똑같은 정삼각형 모양 조각 여러 개를 이어 붙여 놓은 모습"}, {"heading": "각의 크기로 나누기: 예각삼각형, 직각삼각형, 둔각삼각형", "paras": ["세 각이 모두 예각인 삼각형은 예각삼각형이에요.", "한 각이 직각인 삼각형은 직각삼각형, 한 각이 둔각인 삼각형은 둔각삼각형이에요.", "삼각형에는 직각이나 둔각이 두 개 있을 수 없어요. 두 개만 있어도 합이 180°가 되거나 넘어 버리기 때문이에요. 그래서 가장 큰 각 하나만 보면 어떤 삼각형인지 알 수 있어요."], "example": "70°, 60°, 50° → 예각삼각형 / 90°, 35°, 55° → 직각삼각형 / 110°, 40°, 30° → 둔각삼각형", "figure": "종이 삼각자의 직각을 대어 보며 세 삼각형의 가장 큰 각을 비교하는 아이 손"}, {"heading": "이렇게 풀어요: 두 가지 기준으로 이름 붙이기", "paras": ["① 변의 길이를 보고 이등변삼각형인지, 정삼각형인지 살펴요. ② 가장 큰 각을 보고 예각·직각·둔각삼각형 중 어느 것인지 정해요.", "한 삼각형에 두 가지 이름이 함께 붙을 수 있어요. 각의 크기가 30°, 30°, 120°인 삼각형은 두 각이 같으니 이등변삼각형이고, 120°가 둔각이니 둔각삼각형이에요."], "example": "세 각이 45°, 45°, 90° → 두 각이 같아 이등변삼각형 + 직각이 있어 직각삼각형", "figure": "삼각형 카드들을 '변'과 '각' 두 기준으로 표 칸에 나누어 놓은 모습"}], "keywords": [{"word": "이등변삼각형", "meaning": "두 변의 길이가 같은 삼각형"}, {"word": "정삼각형", "meaning": "세 변의 길이가 모두 같은 삼각형"}, {"word": "예각삼각형", "meaning": "세 각이 모두 예각인 삼각형"}, {"word": "직각삼각형", "meaning": "한 각이 직각인 삼각형"}, {"word": "둔각삼각형", "meaning": "한 각이 둔각인 삼각형"}], "expressions": [], "quiz": [{"q": "세 변의 길이가 6cm, 6cm, 4cm인 삼각형의 이름은 무엇일까요?", "choices": ["정삼각형", "이등변삼각형", "직각삼각형", "세 변이 모두 다른 삼각형"], "answer": 1, "explain": "두 변의 길이가 6cm로 같으니 이등변삼각형이에요."}, {"q": "정삼각형의 한 각의 크기는 몇 도일까요?", "choices": ["90°", "45°", "60°", "30°"], "answer": 2, "explain": "세 각이 모두 같고 합이 180°이니 180° ÷ 3 = 60°예요."}, {"q": "세 각이 100°, 50°, 30°인 삼각형은 무엇일까요?", "choices": ["둔각삼각형", "예각삼각형", "직각삼각형", "정삼각형"], "answer": 0, "explain": "100°는 둔각이므로 둔각삼각형이에요."}, {"q": "이등변삼각형에서 크기가 같은 두 각이 각각 65°일 때 나머지 한 각은 몇 도일까요?", "choices": ["65°", "115°", "60°", "50°"], "answer": 3, "explain": "180° − 65° − 65° = 50°예요."}, {"q": "다음 중 옳은 것은 무엇일까요?", "choices": ["직각삼각형에는 직각이 두 개 있어요.", "정삼각형은 이등변삼각형이라고 할 수 있어요.", "예각삼각형에는 둔각이 하나 있어요.", "이등변삼각형의 세 각은 항상 모두 달라요."], "answer": 1, "explain": "정삼각형은 세 변이 같으니 두 변이 같다는 조건도 만족해 이등변삼각형이에요."}], "summary": ["두 변의 길이가 같으면 이등변삼각형, 세 변이 모두 같으면 정삼각형이에요.", "이등변삼각형은 두 각의 크기가 같고, 정삼각형은 세 각이 모두 60°예요.", "가장 큰 각이 예각이면 예각삼각형, 직각이면 직각삼각형, 둔각이면 둔각삼각형이에요."], "parent_tip": "아이들은 '예각삼각형'을 예각이 하나라도 있는 삼각형으로 오해하기 쉽습니다. 어느 삼각형이든 예각은 적어도 두 개 있으므로 '가장 큰 각'을 보고 판단하게 해 주세요. 또 정삼각형도 이등변삼각형에 속한다는 점을 헷갈리니, 빨대나 종이로 직접 만들어 접어 보며 확인하면 좋습니다."}$j$::jsonb,403) on conflict (slug) do update set grade=4,semester=excluded.semester,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,grade,semester,subject,name,sort_order,lesson_slug) select '3~4',4,1,'수학','삼각형',403,'m4-04' where not exists (select 1 from public.topics where lesson_slug='m4-04');
insert into public.lessons (slug,band,grade,semester,subject,topic,title,hero_image,content,sort_order) values ('m4-05','3~4',4,1,'수학','막대그래프','막대그래프로 한눈에 비교해 볼까?','assets/img/l_m4-05.jpg',$j${"intro": "우리 반 친구들이 가장 좋아하는 과일은 무엇일까요? 숫자가 가득한 표보다 막대의 길이로 보면 어느 쪽이 많은지 금방 알 수 있어요.", "sections": [{"heading": "막대그래프는 수량을 막대로 나타내요", "paras": ["조사한 자료의 수량을 막대의 길이로 나타낸 그래프를 막대그래프라고 해요.", "막대가 길수록 수량이 많고, 짧을수록 수량이 적어요. 그래서 여러 항목의 크기를 한눈에 비교할 수 있어요.", "표는 정확한 수를 알아보기 쉽고, 막대그래프는 많고 적음을 비교하기 쉬워요."], "example": "좋아하는 과일 조사: 사과 8명, 귤 5명, 포도 7명, 딸기 10명 → 막대가 가장 긴 딸기를 가장 많은 친구가 좋아해요.", "figure": "좋아하는 과일별 학생 수를 세로 막대 네 개로 나타낸 막대그래프"}, {"heading": "가로, 세로, 눈금을 먼저 살펴요", "paras": ["막대그래프에는 제목, 가로, 세로, 눈금이 있어요. 과일 그래프에서 가로는 과일 이름을, 세로는 학생 수를 나타내요.", "그래프를 읽을 때는 세로 눈금 한 칸이 얼마를 나타내는지 먼저 확인해요. 한 칸이 1명일 때도 있고, 2명이나 5명일 때도 있어요.", "막대 끝이 닿은 눈금을 읽으면 그 항목의 수량을 알 수 있어요."], "example": "세로 눈금 5칸이 10명을 나타내면 한 칸은 10 ÷ 5 = 2(명)이에요. 막대가 4칸이면 2 × 4 = 8(명)이에요.", "figure": "세로 눈금 옆에 0, 2, 4, 6, 8, 10이 적힌 막대그래프의 눈금 부분을 확대한 그림"}, {"heading": "이렇게 그려요: 막대그래프 그리기", "paras": ["① 가로와 세로에 각각 무엇을 나타낼지 정해요. ② 가장 큰 수량까지 나타낼 수 있도록 눈금 한 칸의 크기와 눈금의 수를 정해요.", "③ 항목마다 수량에 맞게 막대를 그려요. 막대의 폭은 모두 같게 해요. ④ 마지막으로 알맞은 제목을 붙여요.", "막대는 세로로 세워 그려도 되고, 가로로 눕혀 그려도 돼요. 눕혀 그리면 가로에 수량을, 세로에 항목을 나타내요."], "example": "가장 큰 수가 10명이고 눈금 한 칸을 1명으로 하면 세로 눈금은 적어도 10칸이 필요해요. 사과는 8칸, 귤은 5칸, 포도는 7칸, 딸기는 10칸 높이로 막대를 그려요.", "figure": "모눈종이에 자를 대고 막대를 색연필로 칠하는 아이 손"}, {"heading": "그래프에서 알 수 있는 것을 찾아요", "paras": ["막대그래프를 보면 가장 많은 것과 가장 적은 것, 많은 순서를 바로 알 수 있어요.", "두 막대의 칸 수 차이를 세면 두 항목이 얼마나 차이 나는지도 알 수 있어요.", "그래프를 보고 '간식으로 딸기를 가장 많이 준비하면 좋겠다.'처럼 생활에 쓸 생각을 말해 볼 수도 있어요."], "example": "딸기 10명, 귤 5명 → 딸기가 귤보다 10 − 5 = 5(명) 더 많아요. 많은 순서는 딸기, 사과, 포도, 귤이에요.", "figure": "가장 긴 막대와 가장 짧은 막대에 동그라미를 친 막대그래프"}, {"heading": "궁금한 것을 조사해 그래프로 나타내요", "paras": ["궁금한 점이 생기면 먼저 무엇을 알고 싶은지 정하고, 친구들에게 묻거나 직접 세어 자료를 모아요.", "모은 자료는 표로 정리한 다음 막대그래프로 나타내요. 합계를 구해 조사한 사람 수와 같은지 확인하면 실수를 줄일 수 있어요.", "마지막으로 그래프를 보고 알게 된 점을 정리해요."], "example": "알고 싶은 것: 우리 반 친구들의 등교 방법 → 걷기 12명, 자전거 4명, 버스 6명, 자동차 3명(합계 25명) → 걸어서 오는 친구가 가장 많아요.", "figure": "친구들에게 받은 붙임쪽지를 등교 방법별로 모아 붙인 칠판"}], "keywords": [{"word": "막대그래프", "meaning": "조사한 자료의 수량을 막대의 길이로 나타낸 그래프"}, {"word": "눈금", "meaning": "그래프에서 수량을 읽을 수 있도록 같은 간격으로 나눈 칸"}, {"word": "항목", "meaning": "조사한 내용을 나눈 하나하나의 종류(예: 사과, 귤, 포도)"}, {"word": "합계", "meaning": "모든 항목의 수량을 더한 값"}], "expressions": [], "quiz": [{"q": "막대그래프에서 막대의 길이는 무엇을 나타낼까요?", "choices": ["항목의 이름", "수량", "조사한 날짜", "그래프의 제목"], "answer": 1, "explain": "막대그래프는 수량을 막대의 길이로 나타내요. 길수록 수량이 많아요."}, {"q": "세로 눈금 5칸이 50명을 나타낼 때, 눈금 한 칸은 몇 명일까요?", "choices": ["5명", "50명", "10명", "1명"], "answer": 2, "explain": "50 ÷ 5 = 10이므로 눈금 한 칸은 10명이에요."}, {"q": "눈금 한 칸이 2권인 막대그래프에서 막대가 7칸이면 몇 권일까요?", "choices": ["7권", "9권", "12권", "14권"], "answer": 3, "explain": "한 칸이 2권이므로 2 × 7 = 14(권)이에요."}, {"q": "축구 9명, 줄넘기 6명, 피구 11명을 막대그래프로 나타내면 막대가 가장 긴 것은 무엇일까요?", "choices": ["피구", "축구", "줄넘기", "모두 같아요"], "answer": 0, "explain": "수량이 가장 많은 피구(11명)의 막대가 가장 길어요."}, {"q": "막대그래프를 그리는 방법으로 알맞지 __않은__ 것은 무엇일까요?", "choices": ["막대의 폭을 모두 같게 해요.", "가장 큰 수량까지 나타낼 수 있게 눈금을 정해요.", "수량이 많은 항목은 막대를 더 굵게 그려요.", "알맞은 제목을 붙여요."], "answer": 2, "explain": "막대그래프는 막대의 길이로 수량을 나타내므로 막대의 폭은 모두 같게 그려야 해요."}], "summary": ["막대그래프는 조사한 수량을 막대의 길이로 나타낸 그래프예요.", "그래프를 읽을 때는 눈금 한 칸이 얼마인지 먼저 확인해요.", "막대그래프를 보면 많고 적음, 순서, 차이를 한눈에 비교할 수 있어요."], "parent_tip": "아이들이 가장 많이 틀리는 부분은 눈금 한 칸을 무조건 1로 읽는 것입니다. 그래프를 볼 때마다 '눈금 한 칸은 얼마일까?'를 먼저 묻게 해 주세요. 가족이 좋아하는 반찬이나 일주일 동안 읽은 책 수를 함께 조사해 모눈종이에 막대그래프로 그려 보면 좋습니다."}$j$::jsonb,404) on conflict (slug) do update set grade=4,semester=excluded.semester,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,grade,semester,subject,name,sort_order,lesson_slug) select '3~4',4,1,'수학','막대그래프',404,'m4-05' where not exists (select 1 from public.topics where lesson_slug='m4-05');
insert into public.lessons (slug,band,grade,semester,subject,topic,title,hero_image,content,sort_order) values ('m4-06','3~4',4,1,'수학','관계와 규칙','규칙을 찾아 수와 식으로 나타내 볼까?','assets/img/l_m4-06.jpg',$j${"intro": "계단을 한 칸 오를 때마다 높이가 똑같이 높아지듯, 우리 주변에는 일정하게 변하는 것이 많아요. 규칙을 찾으면 다음에 올 수도 미리 알 수 있어요.", "sections": [{"heading": "함께 변하는 두 양에서 규칙을 찾아요", "paras": ["세발자전거가 1대 늘어날 때마다 바퀴는 3개씩 늘어나요. 이처럼 한 양이 변하면 다른 양도 따라 변하는 경우가 많아요.", "두 양을 표로 정리하면 어떻게 변하는지 쉽게 보여요. 표를 보고 '자전거 수에 3을 곱하면 바퀴 수가 돼요.'처럼 규칙을 말로 설명해요."], "example": "세발자전거 1대 → 바퀴 3개, 2대 → 6개, 3대 → 9개, 4대 → 12개 → 세발자전거가 6대면 바퀴는 6 × 3 = 18(개)예요.", "figure": "세발자전거 장난감을 한 대, 두 대, 세 대씩 줄지어 놓은 모습"}, {"heading": "수의 배열에서 규칙을 찾아요", "paras": ["수가 놓인 표에서 오른쪽, 아래쪽, 비스듬한 방향으로 수가 어떻게 변하는지 살펴봐요.", "수가 일정하게 커지거나 작아지면 얼마씩 변하는지 찾아요. 어떤 배열은 같은 수를 곱해 가며 커지기도 해요.", "찾은 규칙을 이용하면 빈칸에 들어갈 수를 알 수 있어요."], "example": "1025, 1125, 1225, 1325, □ → 100씩 커지므로 □ = 1425 / 3, 6, 12, 24, □ → 2씩 곱하므로 □ = 48", "figure": "가로와 세로로 수가 적힌 수 배열표에서 한 줄을 형광펜으로 칠한 모습"}, {"heading": "모양의 배열을 수와 식으로 나타내요", "paras": ["바둑돌을 놓는 모양이 규칙적으로 바뀌면 바둑돌의 수도 규칙적으로 변해요.", "순서마다 바둑돌 수를 식으로 써 보면 규칙이 더 잘 보여요. 첫째 1, 둘째 1 + 2, 셋째 1 + 2 + 2처럼 쓰면 2개씩 늘어난다는 것을 알 수 있어요."], "example": "첫째 1개, 둘째 3개, 셋째 5개, 넷째 7개 → 2개씩 늘어나므로 다섯째는 7 + 2 = 9(개)예요.", "figure": "바둑돌을 ㄱ자 모양으로 1개, 3개, 5개씩 늘려 놓은 모습"}, {"heading": "이렇게 풀어요: 계산식 배열의 규칙", "paras": ["계산식이 차례로 놓여 있으면 식의 수가 어떻게 바뀌고, 계산 결과가 어떻게 바뀌는지 함께 살펴봐요.", "① 곱하는 수가 얼마씩 커지는지 봐요. ② 계산 결과가 얼마씩 변하는지 봐요. ③ 찾은 규칙으로 다음 식과 결과를 추측하고, 직접 계산해서 맞는지 확인해요."], "example": "37 × 3 = 111, 37 × 6 = 222, 37 × 9 = 333 → 곱하는 수가 3씩 커지면 결과는 111씩 커져요. 다음 식은 37 × 12 = 444예요.", "figure": "공책에 계산식을 위아래로 나란히 쓰고 바뀌는 수에 동그라미를 친 모습"}, {"heading": "등호(=)는 양쪽이 같다는 뜻이에요", "paras": ["등호(=)는 '답을 쓰세요.'라는 표시가 아니라, 왼쪽과 오른쪽의 크기가 같다는 표시예요. 그래서 7 + 8 = 10 + 5처럼 양쪽에 모두 식이 올 수도 있어요.", "등호가 있는 식이 옳은지 알아볼 때는 양쪽을 각각 계산해 비교해요. 수가 어떻게 바뀌었는지 살피면 계산하지 않고도 알 수 있어요.", "한쪽에서 한 수가 4만큼 커지면, 크기가 같아지도록 다른 수는 4만큼 작아져야 해요."], "example": "16 + 27 = 20 + □ → 16이 20으로 4만큼 커졌으니 27은 4만큼 작아져야 해요. □ = 23 (확인: 16 + 27 = 43, 20 + 23 = 43)", "figure": "양팔 저울 양쪽에 수 카드 묶음을 올려 수평을 이룬 모습"}], "keywords": [{"word": "규칙", "meaning": "수나 모양이 일정하게 바뀌는 약속"}, {"word": "배열", "meaning": "수나 모양을 차례대로 늘어놓은 것"}, {"word": "계산식", "meaning": "덧셈, 뺄셈, 곱셈, 나눗셈 기호를 써서 계산을 나타낸 식"}, {"word": "등호(=)", "meaning": "왼쪽과 오른쪽의 크기가 같다는 것을 나타내는 기호"}], "expressions": [], "quiz": [{"q": "2, 5, 8, 11, □ 에서 □ 안에 알맞은 수는 무엇일까요?", "choices": ["13", "14", "15", "12"], "answer": 1, "explain": "3씩 커지는 규칙이므로 11 + 3 = 14예요."}, {"q": "의자 1개에 다리가 4개 있어요. 의자 7개의 다리는 모두 몇 개일까요?", "choices": ["11개", "24개", "28개", "32개"], "answer": 2, "explain": "의자 수에 4를 곱하면 다리 수예요. 7 × 4 = 28(개)예요."}, {"q": "101 × 11 = 1111, 102 × 11 = 1122, 103 × 11 = 1133 다음에 올 식은 무엇일까요?", "choices": ["104 × 11 = 1144", "104 × 12 = 1144", "103 × 12 = 1144", "104 × 11 = 1134"], "answer": 0, "explain": "앞의 수가 1씩 커지면 결과는 11씩 커져요. 104 × 11 = 1144예요."}, {"q": "등호(=)를 바르게 쓴 식은 무엇일까요?", "choices": ["9 + 6 = 10 + 6", "12 − 4 = 10 − 4", "20 + 5 = 20 − 5", "9 + 6 = 10 + 5"], "answer": 3, "explain": "9 + 6 = 15, 10 + 5 = 15로 양쪽 크기가 같아요."}, {"q": "25 + 38 = 30 + □ 에서 □ 안에 알맞은 수는 무엇일까요?", "choices": ["43", "33", "38", "28"], "answer": 1, "explain": "25가 30으로 5만큼 커졌으니 38은 5만큼 작아져야 해요. 38 − 5 = 33이에요."}], "summary": ["함께 변하는 두 양은 표로 정리하면 규칙이 잘 보여요.", "수나 모양, 계산식의 배열에서 규칙을 찾으면 다음을 추측할 수 있어요.", "등호(=)는 양쪽의 크기가 같다는 뜻이에요."], "parent_tip": "많은 아이가 등호를 '답을 쓰는 자리'로만 생각해서 16 + 27 = □ + 25 같은 식에서 □에 43을 쓰는 실수를 합니다. '등호 양쪽이 저울처럼 같아야 해.'라고 설명해 주세요. 계단 수와 높이, 자동차 수와 바퀴 수처럼 생활 속에서 함께 변하는 두 양을 찾아 표로 만들어 보는 놀이도 좋습니다."}$j$::jsonb,405) on conflict (slug) do update set grade=4,semester=excluded.semester,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,grade,semester,subject,name,sort_order,lesson_slug) select '3~4',4,1,'수학','관계와 규칙',405,'m4-06' where not exists (select 1 from public.topics where lesson_slug='m4-06');
insert into public.lessons (slug,band,grade,semester,subject,topic,title,hero_image,content,sort_order) values ('m4-07','3~4',4,2,'수학','분수의 덧셈과 뺄셈','분모가 같은 분수, 어떻게 더하고 뺄까?','assets/img/l_m4-07.jpg',$j${"intro": "피자 한 판을 똑같이 8조각으로 나누어 내가 3조각, 동생이 2조각을 먹었어요. 둘이 먹은 양은 피자 한 판의 얼마일까요?", "sections": [{"heading": "분모가 같으면 분자끼리 더해요", "paras": ["3/8은 1/8이 3개, 2/8는 1/8이 2개예요. 그러니까 3/8 + 2/8는 1/8이 모두 5개, 곧 5/8예요.", "분모가 같은 분수의 덧셈은 분모는 그대로 두고 분자끼리 더해요. 분모까지 더하면 한 조각의 크기가 바뀌어 버리니 조심해요."], "example": "3/8 + 2/8 → 1/8이 3 + 2 = 5(개) → 5/8", "figure": "똑같이 8조각으로 나눈 피자에서 5조각에 색칠한 모습"}, {"heading": "합이 1보다 크면 대분수로 나타내요", "paras": ["진분수끼리 더했는데 분자가 분모보다 커지면 가분수가 돼요.", "가분수는 대분수로 바꾸어 나타낼 수 있어요. 분모만큼 모이면 1이 되니까, 1을 자연수로 떼어 내요."], "example": "4/6 + 5/6 = 9/6 → 6/6은 1이므로 9/6 = 1과 3/6", "figure": "6조각으로 나눈 원 모양 종이 두 장 중 한 장은 다 칠하고 다른 한 장은 3조각을 칠한 모습"}, {"heading": "이렇게 풀어요: 대분수의 덧셈", "paras": ["방법 1: 자연수는 자연수끼리, 분수는 분수끼리 더해요. 분수끼리 더한 값이 1보다 크면 1을 자연수로 올려 줘요.", "방법 2: 두 대분수를 가분수로 바꾸어 분자끼리 더한 다음, 다시 대분수로 바꿔요. 두 방법의 답은 같아요."], "example": "1과 2/5 + 2와 4/5 ① 자연수끼리 1 + 2 = 3 ② 분수끼리 2/5 + 4/5 = 6/5 = 1과 1/5 ③ 3 + 1과 1/5 = 4와 1/5", "figure": "5칸으로 나눈 막대 모형을 이어 붙여 대분수의 덧셈을 나타낸 모습"}, {"heading": "분모가 같은 분수의 뺄셈", "paras": ["뺄셈도 분모는 그대로 두고 분자끼리 빼요. 6/7 − 2/7는 1/7이 6개에서 2개를 뺀 것이니 4/7예요.", "대분수끼리 뺄 때는 자연수는 자연수끼리, 분수는 분수끼리 빼요. 가분수로 바꾸어 계산해도 돼요."], "example": "3과 5/9 − 1과 2/9 → 자연수 3 − 1 = 2, 분수 5/9 − 2/9 = 3/9 → 2와 3/9", "figure": "9칸으로 나눈 띠 종이에서 몇 칸을 가위로 잘라 내는 아이 손"}, {"heading": "이렇게 풀어요: (자연수) − (분수)와 받아내림", "paras": ["자연수에서 분수를 뺄 때는 자연수에서 1을 분모가 같은 분수로 바꿔요. 분모가 5이면 1 = 5/5예요.", "대분수끼리 뺄 때 빼지는 분수가 빼는 분수보다 작으면, 자연수에서 1을 받아내려 분수에 더한 다음 계산해요."], "example": "3 − 1과 2/5 = 2와 5/5 − 1과 2/5 = 1과 3/5 / 4와 1/6 − 1과 5/6 = 3과 7/6 − 1과 5/6 = 2와 2/6", "figure": "리본 3 m 가운데 1 m를 다섯 칸으로 나누어 표시한 모습"}], "keywords": [{"word": "분모", "meaning": "분수에서 전체를 똑같이 나눈 수로, 가로선 아래에 쓰는 수"}, {"word": "분자", "meaning": "분수에서 전체 중 차지하는 부분의 수로, 가로선 위에 쓰는 수"}, {"word": "진분수", "meaning": "분자가 분모보다 작은 분수(예: 3/5)"}, {"word": "가분수", "meaning": "분자가 분모와 같거나 분모보다 큰 분수(예: 7/5)"}, {"word": "대분수", "meaning": "자연수와 진분수로 이루어진 분수(예: 1과 2/5)"}], "expressions": [], "quiz": [{"q": "2/9 + 5/9 는 얼마일까요?", "choices": ["7/18", "7/9", "3/9", "10/9"], "answer": 1, "explain": "분모는 그대로 두고 분자끼리 더해요. 2 + 5 = 7이므로 7/9이에요."}, {"q": "5/7 + 4/7 을 계산하여 대분수로 나타낸 것은 무엇일까요?", "choices": ["9/14", "1과 1/7", "1과 2/7", "2와 2/7"], "answer": 2, "explain": "5/7 + 4/7 = 9/7이고, 7/7이 1이므로 1과 2/7예요."}, {"q": "2와 3/8 + 1과 6/8 은 얼마일까요?", "choices": ["4와 1/8", "3과 9/16", "3과 1/8", "4와 3/8"], "answer": 0, "explain": "자연수끼리 3, 분수끼리 9/8 = 1과 1/8 → 3 + 1과 1/8 = 4와 1/8이에요."}, {"q": "5 − 2/3 은 얼마일까요?", "choices": ["3과 1/3", "4와 2/3", "3/3", "4와 1/3"], "answer": 3, "explain": "5를 4와 3/3으로 바꾸면 4와 3/3 − 2/3 = 4와 1/3이에요."}, {"q": "물 2와 1/4 L 가운데 3/4 L를 마셨어요. 남은 물은 몇 L일까요?", "choices": ["1과 2/4 L", "2와 2/4 L", "1과 3/4 L", "3 L"], "answer": 0, "explain": "2와 1/4을 1과 5/4로 바꾸면 1과 5/4 − 3/4 = 1과 2/4(L)예요."}], "summary": ["분모가 같은 분수의 덧셈과 뺄셈은 분모는 그대로 두고 분자끼리 계산해요.", "분수끼리 더한 값이 가분수가 되면 대분수로 바꾸어 나타내요.", "자연수나 대분수에서 뺄 수 없으면 1을 분모가 같은 분수로 바꾸어 받아내려요."], "parent_tip": "가장 흔한 실수는 2/9 + 5/9 = 7/18처럼 분모끼리도 더하는 것입니다. '1/9짜리 조각이 몇 개인지 세는 것'이라고 말해 주면 분모가 바뀌지 않는 까닭을 쉽게 이해합니다. 이 단원에서는 약분을 배우지 않으므로 2/6를 1/3로 고치지 않아도 정답입니다. 피자나 케이크를 나눌 때 '몇 조각 남았지?'를 분수로 말해 보게 해 주세요."}$j$::jsonb,406) on conflict (slug) do update set grade=4,semester=excluded.semester,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,grade,semester,subject,name,sort_order,lesson_slug) select '3~4',4,2,'수학','분수의 덧셈과 뺄셈',406,'m4-07' where not exists (select 1 from public.topics where lesson_slug='m4-07');
insert into public.lessons (slug,band,grade,semester,subject,topic,title,hero_image,content,sort_order) values ('m4-08','3~4',4,2,'수학','사각형','수직과 평행으로 사각형을 알아볼까?','assets/img/l_m4-08.jpg',$j${"intro": "공책의 줄은 아무리 길게 그어도 서로 만나지 않고, 창틀의 가로와 세로는 반듯하게 만나요. 이런 선의 관계를 알면 여러 가지 사각형의 특징이 눈에 들어와요.", "sections": [{"heading": "수직과 수선", "paras": ["두 직선이 만나서 이루는 각이 직각일 때, 두 직선은 서로 수직이라고 해요.", "두 직선이 서로 수직으로 만나면, 한 직선을 다른 직선에 대한 수선이라고 해요.", "삼각자의 직각 부분이나 각도기의 90° 눈금을 이용하면 수선을 그을 수 있어요."], "example": "직선 가와 직선 나가 만나서 이루는 각이 90°예요. → 직선 가와 직선 나는 서로 수직이고, 직선 가는 직선 나에 대한 수선이에요.", "figure": "삼각자의 직각 부분을 직선에 대고 수선을 긋는 아이 손"}, {"heading": "평행과 평행선 사이의 거리", "paras": ["한 직선에 수직인 두 직선을 그으면, 이 두 직선은 아무리 길게 늘여도 서로 만나지 않아요. 이렇게 서로 만나지 않는 두 직선을 평행하다고 하고, 평행한 두 직선을 평행선이라고 해요.", "평행선의 한 직선에서 다른 직선에 수선을 그었을 때, 그 수선의 길이를 평행선 사이의 거리라고 해요.", "평행선 사이의 거리는 어느 곳에서 재어도 모두 같아요. 수선이 아니라 비스듬히 그은 선분은 거리보다 길어요."], "example": "평행선 사이에 수선을 세 군데 긋고 재면 3 cm, 3 cm, 3 cm로 모두 같아요. → 평행선 사이의 거리는 3 cm예요.", "figure": "공책의 평행한 두 줄 사이에 자를 수직으로 세워 길이를 재는 모습"}, {"heading": "사다리꼴과 평행사변형", "paras": ["평행한 변이 한 쌍이라도 있는 사각형을 사다리꼴이라고 해요.", "마주 보는 두 쌍의 변이 서로 평행한 사각형을 평행사변형이라고 해요.", "평행사변형은 마주 보는 두 변의 길이가 같고, 마주 보는 두 각의 크기가 같아요. 또 이웃한 두 각의 크기를 더하면 180°예요."], "example": "평행사변형의 한 각이 65°이면 마주 보는 각도 65°이고, 이웃한 각은 180° − 65° = 115°예요.", "figure": "색종이를 잘라 만든 사다리꼴과 평행사변형을 나란히 놓고 평행한 변에 같은 색 표시를 한 모습"}, {"heading": "마름모", "paras": ["네 변의 길이가 모두 같은 사각형을 마름모라고 해요.", "마름모는 마주 보는 두 쌍의 변이 서로 평행하고, 마주 보는 두 각의 크기가 같아요. 이웃한 두 각의 크기를 더하면 180°예요."], "example": "한 변이 7 cm인 마름모의 네 변의 길이의 합은 7 × 4 = 28(cm)예요.", "figure": "길이가 같은 빨대 네 개를 이어 비스듬히 기울인 마름모 모양"}, {"heading": "이렇게 풀어요: 사각형의 성질로 길이와 각도 구하기", "paras": ["직사각형은 네 각이 모두 직각이고 마주 보는 두 변의 길이가 같아요. 정사각형은 네 각이 모두 직각이고 네 변의 길이가 모두 같아요.", "모르는 길이나 각도를 구할 때는 ① 어떤 사각형인지 확인하고, ② 그 사각형의 성질(길이가 같은 변, 크기가 같은 각, 이웃한 두 각의 합 180°)을 떠올린 다음, ③ 식을 세워 계산해요."], "example": "평행사변형의 두 변이 8 cm, 5 cm이면 마주 보는 변의 길이가 같으므로 네 변의 길이의 합은 8 + 5 + 8 + 5 = 26(cm)예요.", "figure": "평행사변형 그림 옆에 같은 길이의 변끼리 같은 표시를 한 공책"}], "keywords": [{"word": "수선", "meaning": "두 직선이 서로 수직으로 만날 때, 한 직선을 다른 직선에 대하여 이르는 말"}, {"word": "평행선", "meaning": "아무리 늘여도 서로 만나지 않는 평행한 두 직선"}, {"word": "평행선 사이의 거리", "meaning": "평행선의 한 직선에서 다른 직선에 그은 수선의 길이"}, {"word": "사다리꼴", "meaning": "평행한 변이 한 쌍이라도 있는 사각형"}, {"word": "평행사변형", "meaning": "마주 보는 두 쌍의 변이 서로 평행한 사각형"}, {"word": "마름모", "meaning": "네 변의 길이가 모두 같은 사각형"}], "expressions": [], "quiz": [{"q": "두 직선이 만나서 이루는 각이 직각일 때, 두 직선은 어떤 관계일까요?", "choices": ["서로 평행해요.", "서로 수직이에요.", "서로 길이가 같아요.", "서로 만나지 않아요."], "answer": 1, "explain": "두 직선이 만나서 이루는 각이 직각이면 두 직선은 서로 수직이에요."}, {"q": "평행선 사이의 거리에 대한 설명으로 옳은 것은 무엇일까요?", "choices": ["재는 곳마다 달라요.", "비스듬히 그은 선분의 길이예요.", "어느 곳에서 재어도 같아요.", "평행선 사이의 거리는 잴 수 없어요."], "answer": 2, "explain": "평행선 사이의 거리는 수선의 길이이고, 어느 곳에서 재어도 같아요."}, {"q": "평행한 변이 한 쌍이라도 있는 사각형을 무엇이라고 할까요?", "choices": ["사다리꼴", "마름모", "정사각형", "직사각형"], "answer": 0, "explain": "평행한 변이 한 쌍이라도 있는 사각형을 사다리꼴이라고 해요."}, {"q": "평행사변형의 한 각이 70°일 때, 이웃한 각의 크기는 몇 도일까요?", "choices": ["70°", "90°", "20°", "110°"], "answer": 3, "explain": "평행사변형에서 이웃한 두 각의 합은 180°이므로 180° − 70° = 110°예요."}, {"q": "네 변의 길이의 합이 36 cm인 마름모가 있어요. 한 변은 몇 cm일까요?", "choices": ["12 cm", "9 cm", "8 cm", "6 cm"], "answer": 1, "explain": "마름모는 네 변의 길이가 모두 같으므로 36 ÷ 4 = 9(cm)예요."}], "summary": ["두 직선이 직각으로 만나면 수직, 만나지 않으면 평행이에요.", "평행선 사이의 거리는 수선의 길이로, 어디서 재어도 같아요.", "사다리꼴, 평행사변형, 마름모는 평행한 변과 변의 길이로 구별해요."], "parent_tip": "아이들은 평행선 사이의 거리를 잴 때 자를 비스듬히 대는 실수를 자주 합니다. 꼭 수선을 그은 뒤 그 길이를 재야 한다는 점을 짚어 주세요. 집 안에서 창틀, 책장, 타일 무늬 등에서 수직과 평행인 곳, 사다리꼴과 평행사변형 모양을 찾아보며 '어떤 변끼리 평행할까?'라고 물어보면 좋습니다."}$j$::jsonb,407) on conflict (slug) do update set grade=4,semester=excluded.semester,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,grade,semester,subject,name,sort_order,lesson_slug) select '3~4',4,2,'수학','사각형',407,'m4-08' where not exists (select 1 from public.topics where lesson_slug='m4-08');
insert into public.lessons (slug,band,grade,semester,subject,topic,title,hero_image,content,sort_order) values ('m4-09','3~4',4,2,'수학','소수의 덧셈과 뺄셈','0.01과 0.001, 소수는 어떻게 더하고 뺄까?','assets/img/l_m4-09.jpg',$j${"intro": "100m 달리기 기록이 15.37초, 내 키가 1.36m처럼 소수점 아래 숫자가 두세 개인 수를 본 적 있나요? 오늘은 더 작은 자리까지 있는 소수를 읽고, 비교하고, 더하고 빼 봐요.", "sections": [{"heading": "0.01과 0.001을 알아봐요", "paras": ["1을 똑같이 100으로 나눈 것 중 하나는 분수로 1/100이고, 소수로 0.01이라고 써요. 읽을 때는 '영 점 영일'이라고 해요.", "1을 똑같이 1000으로 나눈 것 중 하나는 1/1000이고, 소수로 0.001이라고 써요. '영 점 영영일'이라고 읽어요. 0.01이 10개 모이면 0.1, 0.001이 10개 모이면 0.01이 돼요."], "example": "1/100 = 0.01 (영 점 영일), 37/100 = 0.37 (영 점 삼칠), 1/1000 = 0.001 (영 점 영영일)", "figure": "모눈 100칸짜리 정사각형에서 1칸만 색칠하고 0.01이라고 적은 그림"}, {"heading": "소수의 자릿값을 알아봐요", "paras": ["소수점 오른쪽 첫 번째 자리는 소수 첫째 자리, 두 번째는 소수 둘째 자리, 세 번째는 소수 셋째 자리예요. 소수 둘째 자리까지 있는 수를 소수 두 자리 수, 셋째 자리까지 있는 수를 소수 세 자리 수라고 해요.", "2.574에서 2는 일의 자리 숫자로 2를, 5는 소수 첫째 자리 숫자로 0.5를, 7은 소수 둘째 자리 숫자로 0.07을, 4는 소수 셋째 자리 숫자로 0.004를 나타내요. 소수점 아래는 숫자를 하나씩 읽어서 '이 점 오칠사'라고 읽어요."], "example": "2.574 = 2 + 0.5 + 0.07 + 0.004", "figure": "2.574의 각 숫자 아래에 일의 자리, 소수 첫째 자리, 소수 둘째 자리, 소수 셋째 자리 이름표를 붙인 자릿값 표"}, {"heading": "소수의 크기를 비교해요", "paras": ["소수의 크기는 자연수 부분부터 비교하고, 같으면 소수 첫째 자리, 그다음 소수 둘째 자리, 소수 셋째 자리 순서로 비교해요. 높은 자리 숫자가 큰 쪽이 더 큰 수예요.", "소수는 오른쪽 끝에 0을 붙여도 크기가 같아요. 0.4와 0.40은 같은 수예요. 그래서 0.4와 0.38을 비교할 때 0.40과 0.38로 자릿수를 맞추면 비교하기 쉬워요. 자릿수가 많다고 더 큰 수가 아니라는 점을 꼭 기억해요."], "example": "0.4와 0.38 비교 → 0.40과 0.38 → 소수 첫째 자리 4 > 3 → 0.4 > 0.38", "figure": "0.4와 0.38을 모눈 100칸 판 두 장에 각각 색칠해서 나란히 놓고 비교하는 그림"}, {"heading": "이렇게 풀어요: 소수의 덧셈", "paras": ["① 소수점끼리 세로로 맞추어 써요. 자릿수가 다르면 끝에 0을 붙여 자리를 맞춰도 돼요. ② 자연수의 덧셈처럼 오른쪽 자리부터 더하고, 10이 넘으면 바로 윗자리로 받아올려요. ③ 답에 소수점을 그대로 내려 찍어요.", "1.35 + 2.48을 해 볼까요? 소수 둘째 자리 5 + 8 = 13이니 3을 쓰고 1을 올려요. 소수 첫째 자리 1 + 3 + 4 = 8, 일의 자리 1 + 2 = 3이에요. 그래서 답은 3.83이에요."], "example": "2.7 + 1.56 → 2.70 + 1.56 → 4.26", "figure": "공책에 2.70과 1.56을 소수점을 세로로 맞추어 쓰고 더하는 세로셈 그림"}, {"heading": "이렇게 풀어요: 소수의 뺄셈", "paras": ["뺄셈도 소수점을 맞추어 쓰고 오른쪽 자리부터 빼요. 뺄 수 없으면 바로 윗자리에서 받아내림을 해요. 0.1 하나를 받아내리면 0.01이 10개가 돼요.", "5.2 − 1.75는 5.20 − 1.75로 바꾸어 계산해요. 소수 둘째 자리는 0에서 5를 뺄 수 없으니 받아내려 10 − 5 = 5, 소수 첫째 자리는 1에서 7을 뺄 수 없으니 다시 받아내려 11 − 7 = 4, 일의 자리 4 − 1 = 3이에요. 답은 3.45이고, 3.45 + 1.75 = 5.2로 검산할 수 있어요."], "example": "5.2 − 1.75 = 3.45 (검산: 3.45 + 1.75 = 5.2)", "figure": "5.20 − 1.75 세로셈에서 받아내림 표시를 작게 적어 둔 그림"}], "keywords": [{"word": "소수 두 자리 수", "meaning": "0.37, 1.25처럼 소수 둘째 자리까지 있는 소수"}, {"word": "소수 세 자리 수", "meaning": "0.125, 2.574처럼 소수 셋째 자리까지 있는 소수"}, {"word": "소수 둘째 자리", "meaning": "소수점 오른쪽 두 번째 자리, 0.01이 몇 개인지 나타내요"}, {"word": "소수 셋째 자리", "meaning": "소수점 오른쪽 세 번째 자리, 0.001이 몇 개인지 나타내요"}, {"word": "소수점 맞추기", "meaning": "소수를 더하거나 뺄 때 소수점을 세로로 같은 줄에 두는 것"}], "expressions": [], "quiz": [{"q": "6.408에서 숫자 8은 얼마를 나타낼까요?", "choices": ["8", "0.8", "0.08", "0.008"], "answer": 3, "explain": "8은 소수 셋째 자리 숫자라서 0.008을 나타내요."}, {"q": "다음 중 가장 큰 수는 무엇일까요?", "choices": ["0.9", "0.89", "0.809", "0.098"], "answer": 0, "explain": "소수 첫째 자리 숫자가 0.9는 9, 0.89와 0.809는 8, 0.098은 0이라서 0.9가 가장 커요."}, {"q": "2.36 + 1.8은 얼마일까요?", "choices": ["2.54", "4.16", "3.16", "4.44"], "answer": 1, "explain": "2.36 + 1.80으로 소수점을 맞추면 4.16이에요. 2.54는 자리를 잘못 맞춘 답이에요."}, {"q": "6.4 − 2.57은 얼마일까요?", "choices": ["4.17", "4.83", "3.83", "3.93"], "answer": 2, "explain": "6.40 − 2.57로 바꾸어 받아내림하면 3.83이에요. 검산: 3.83 + 2.57 = 6.4"}, {"q": "0.01이 35개인 수는 무엇일까요?", "choices": ["3.5", "0.035", "35", "0.35"], "answer": 3, "explain": "0.01이 10개면 0.1이니, 35개면 0.1이 3개, 0.01이 5개로 0.35예요."}], "summary": ["1/100 = 0.01, 1/1000 = 0.001이고, 소수점 아래 자리는 소수 첫째·둘째·셋째 자리예요.", "소수의 크기는 높은 자리부터 차례로 비교하고, 끝에 0을 붙여 자릿수를 맞추면 쉬워요.", "소수의 덧셈과 뺄셈은 소수점을 세로로 맞추고 자연수처럼 계산한 뒤 소수점을 내려 찍어요."], "parent_tip": "아이들이 가장 많이 하는 실수는 0.38이 0.4보다 크다고 생각하는 것과, 2.36 + 1.8에서 숫자를 오른쪽 끝에 맞춰 더하는 것입니다. 세로셈에서 소수점을 먼저 세로로 맞추고 빈자리에 0을 써 넣도록 해 주세요. 마트 영수증이나 키·몸무게 기록(1.36m 등)을 보며 '이 숫자는 얼마를 나타낼까?' 하고 물어보면 자릿값 감각이 좋아집니다."}$j$::jsonb,408) on conflict (slug) do update set grade=4,semester=excluded.semester,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,grade,semester,subject,name,sort_order,lesson_slug) select '3~4',4,2,'수학','소수의 덧셈과 뺄셈',408,'m4-09' where not exists (select 1 from public.topics where lesson_slug='m4-09');
insert into public.lessons (slug,band,grade,semester,subject,topic,title,hero_image,content,sort_order) values ('m4-10','3~4',4,2,'수학','다각형','변이 많아지면 어떤 도형이 될까? 다각형과 대각선','assets/img/l_m4-10.jpg',$j${"intro": "축구공 무늬, 벌집, 욕실 바닥 타일을 자세히 보면 오각형과 육각형이 숨어 있어요. 선분으로 둘러싸인 여러 가지 도형의 이름과 성질을 알아보고, 모양 조각으로 빈틈없이 채워 봐요.", "sections": [{"heading": "선분으로만 둘러싸인 도형, 다각형", "paras": ["선분으로만 둘러싸인 도형을 다각형이라고 해요. 다각형은 변의 수에 따라 이름이 정해져요. 변이 5개면 오각형, 6개면 육각형, 8개면 팔각형이에요.", "원처럼 굽은 선이 있거나, 선분이 끝까지 이어지지 않아 열려 있는 도형은 다각형이 아니에요. 다각형은 변의 수와 꼭짓점의 수가 언제나 같아요."], "example": "변 7개, 꼭짓점 7개 → 칠각형", "figure": "오각형, 육각형, 팔각형과 함께 원, 한쪽이 열린 도형을 나란히 그려 다각형인 것과 아닌 것을 나눈 그림"}, {"heading": "변도 각도 모두 같은 정다각형", "paras": ["변의 길이가 모두 같고, 각의 크기도 모두 같은 다각형을 정다각형이라고 해요. 정삼각형, 정사각형, 정오각형, 정육각형처럼 이름 앞에 '정'을 붙여요.", "두 가지 조건을 모두 만족해야 해요. 마름모는 네 변의 길이가 같지만 네 각의 크기가 다를 수 있어서 정다각형이라고 할 수 없어요. 직사각형도 네 각은 같지만 네 변의 길이가 다를 수 있어서 정다각형이 아니에요."], "example": "한 변이 6cm인 정오각형의 모든 변의 길이의 합 → 6 × 5 = 30(cm)", "figure": "정사각형, 마름모, 직사각형을 나란히 그리고 변의 길이와 각의 크기를 표시해 비교한 그림"}, {"heading": "대각선을 그어 봐요", "paras": ["다각형에서 서로 이웃하지 않는 두 꼭짓점을 이은 선분을 대각선이라고 해요. 삼각형은 세 꼭짓점이 모두 서로 이웃해 있어서 대각선을 그을 수 없어요.", "사각형에는 대각선이 2개, 오각형에는 5개, 육각형에는 9개 있어요. 한 꼭짓점에서 그을 수 있는 대각선부터 차근차근 세어 보면 빠뜨리지 않아요."], "example": "오각형: 한 꼭짓점에서 2개씩, 꼭짓점 5개 → 2 × 5 = 10, 같은 대각선을 두 번씩 셌으니 10 ÷ 2 = 5(개)", "figure": "사각형, 오각형, 육각형에 대각선을 모두 그어 색연필로 표시한 그림"}, {"heading": "사각형의 대각선에는 성질이 있어요", "paras": ["직사각형과 정사각형은 두 대각선의 길이가 같아요. 마름모와 정사각형은 두 대각선이 서로 수직으로 만나요.", "평행사변형, 마름모, 직사각형, 정사각형은 한 대각선이 다른 대각선을 똑같이 둘로 나누어요. 그래서 두 대각선이 만나는 점에서 각 꼭짓점까지의 길이를 짝지어 보면 서로 같아요."], "example": "정사각형의 대각선 → 두 대각선의 길이가 같고, 서로 수직으로 만나고, 서로를 반으로 나눠요.", "figure": "직사각형, 마름모, 정사각형에 대각선을 긋고 길이가 같은 부분과 직각 표시를 한 그림"}, {"heading": "이렇게 풀어요: 모양 조각으로 채우기", "paras": ["모양 조각에는 정삼각형, 정사각형, 정육각형, 사다리꼴, 마름모, 평행사변형이 있어요. 정육각형 하나는 정삼각형 6개, 또는 사다리꼴 2개, 또는 마름모 3개로 똑같이 채울 수 있어요.", "바닥을 빈틈없이 채울 때는 한 점에 모인 각의 합이 360°가 되어야 해요. ① 정삼각형 한 각은 60°라서 6개를 모으면 360° ② 정사각형 한 각은 90°라서 4개면 360° ③ 정육각형 한 각은 120°라서 3개면 360°예요. 정오각형 한 각은 108°라서 3개는 324°로 틈이 생기고 4개는 432°로 겹쳐서, 정오각형만으로는 빈틈없이 채울 수 없어요."], "example": "정육각형 1개 = 정삼각형 6개 = 사다리꼴 2개 = 마름모 3개", "figure": "정육각형 위에 정삼각형 6개, 사다리꼴 2개, 마름모 3개를 각각 올려 채운 세 가지 모양 조각 그림"}], "keywords": [{"word": "다각형", "meaning": "선분으로만 둘러싸인 도형"}, {"word": "정다각형", "meaning": "변의 길이가 모두 같고 각의 크기도 모두 같은 다각형"}, {"word": "대각선", "meaning": "서로 이웃하지 않는 두 꼭짓점을 이은 선분"}, {"word": "오각형·육각형", "meaning": "변이 5개인 다각형, 변이 6개인 다각형"}, {"word": "모양 조각", "meaning": "정삼각형, 사다리꼴, 마름모 등 모양을 만들거나 채울 때 쓰는 도형 조각"}], "expressions": [], "quiz": [{"q": "변이 8개인 다각형의 이름은 무엇일까요?", "choices": ["육각형", "칠각형", "팔각형", "구각형"], "answer": 2, "explain": "다각형은 변의 수로 이름을 붙여요. 변이 8개면 팔각형이에요."}, {"q": "다음 중 정다각형인 것은 무엇일까요?", "choices": ["정사각형", "마름모", "직사각형", "평행사변형"], "answer": 0, "explain": "정사각형은 네 변의 길이와 네 각의 크기가 모두 같아요. 마름모는 각이, 직사각형은 변이 다를 수 있어요."}, {"q": "육각형에 그을 수 있는 대각선은 모두 몇 개일까요?", "choices": ["6개", "9개", "3개", "12개"], "answer": 1, "explain": "한 꼭짓점에서 3개씩, 꼭짓점 6개라 3 × 6 = 18인데 두 번씩 셌으니 18 ÷ 2 = 9개예요."}, {"q": "두 대각선의 길이가 항상 같은 사각형은 무엇일까요?", "choices": ["마름모", "사다리꼴", "평행사변형", "직사각형"], "answer": 3, "explain": "직사각형은 두 대각선의 길이가 같아요. 마름모, 사다리꼴, 평행사변형은 두 대각선의 길이가 다를 수 있어요."}, {"q": "한 가지 정다각형만으로 바닥을 빈틈없이 채울 수 없는 것은 무엇일까요?", "choices": ["정삼각형", "정사각형", "정오각형", "정육각형"], "answer": 2, "explain": "정오각형 한 각은 108°라서 한 점에 3개 모으면 324°로 틈이 생기고, 4개면 432°로 겹쳐요."}], "summary": ["선분으로만 둘러싸인 도형이 다각형이고, 변의 수에 따라 오각형, 육각형처럼 이름을 붙여요.", "변의 길이와 각의 크기가 모두 같은 다각형이 정다각형이에요.", "대각선은 이웃하지 않는 두 꼭짓점을 이은 선분이고, 모양 조각으로 여러 모양을 만들거나 빈틈없이 채울 수 있어요."], "parent_tip": "아이들은 마름모를 정다각형으로, 원을 다각형으로 착각하기 쉽습니다. 정다각형은 '변도 같고 각도 같아야 한다'는 두 조건을 함께 확인하게 해 주세요. 대각선을 셀 때는 한 꼭짓점씩 차례로 그어 보며 같은 선을 두 번 세지 않도록 하고, 욕실 타일이나 보도블록을 보며 '어떤 도형으로 빈틈없이 채웠을까?'라고 물어보면 좋습니다."}$j$::jsonb,409) on conflict (slug) do update set grade=4,semester=excluded.semester,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,grade,semester,subject,name,sort_order,lesson_slug) select '3~4',4,2,'수학','다각형',409,'m4-10' where not exists (select 1 from public.topics where lesson_slug='m4-10');
insert into public.lessons (slug,band,grade,semester,subject,topic,title,hero_image,content,sort_order) values ('m4-11','3~4',4,2,'수학','꺾은선그래프','시간에 따라 어떻게 변했을까? 꺾은선그래프','assets/img/l_m4-11.jpg',$j${"intro": "아침보다 낮에 더 덥고, 강낭콩 싹은 날마다 조금씩 자라요. 이렇게 시간이 지나면서 달라지는 모습을 한눈에 보여 주는 그래프가 바로 꺾은선그래프예요.", "sections": [{"heading": "꺾은선그래프는 무엇일까요?", "paras": ["수량을 점으로 찍고, 그 점들을 차례로 선분으로 이어 그린 그래프를 꺾은선그래프라고 해요. 보통 가로에는 시각이나 날짜처럼 시간을, 세로에는 기온이나 키처럼 변하는 양을 나타내요.", "선분이 이어져 있어서 양이 늘어나는지 줄어드는지, 얼마나 빨리 변하는지를 한눈에 알 수 있어요."], "example": "가로: 시각(오전 9시, 10시, …), 세로: 기온(°C) → 시각별 기온을 점으로 찍고 선분으로 이어요.", "figure": "모눈 위에 시각별 기온을 점으로 찍고 선분으로 이은 꺾은선그래프 그림"}, {"heading": "이렇게 읽어요: 선의 기울어진 정도", "paras": ["선분이 오른쪽 위로 올라가면 양이 늘어난 것이고, 오른쪽 아래로 내려가면 줄어든 것이에요. 선분이 많이 기울어질수록 변화가 크고, 거의 평평하면 변화가 작아요.", "아래 표를 꺾은선그래프로 그리면 오전 10시에서 11시 사이 선분이 가장 많이 기울어져요. 이때 기온이 4°C로 가장 많이 올랐어요. 오후 1시부터 2시 사이에는 선분이 내려가서 기온이 2°C 낮아졌어요."], "example": "시각별 기온: 오전 9시 12°C, 10시 15°C, 11시 19°C, 낮 12시 22°C, 오후 1시 23°C, 2시 21°C", "figure": "시각별 기온 꺾은선그래프에서 가장 가파른 선분(10시~11시)을 빨간색으로 강조한 그림"}, {"heading": "재지 않은 때의 값도 어림할 수 있어요", "paras": ["꺾은선그래프는 점과 점 사이가 선분으로 이어져 있어서, 재지 않은 중간 시각의 값도 어림해 볼 수 있어요.", "오전 10시에 15°C, 11시에 19°C였다면 오전 10시 30분에는 그 사이쯤인 약 17°C였을 거라고 어림할 수 있어요. 정확한 값은 아니고 '약'을 붙여 말하는 어림값이에요."], "example": "10시 15°C와 11시 19°C의 가운데 → 10시 30분 약 17°C", "figure": "두 점을 이은 선분의 가운데에 작은 점을 찍고 '약 17°C'라고 적은 그림"}, {"heading": "물결선으로 필요 없는 부분을 줄여요", "paras": ["값이 모두 크고 변화가 작으면 그래프 대부분이 빈칸이 되고 선은 거의 평평해 보여요. 이럴 때는 세로 눈금에서 필요 없는 아랫부분을 물결선(≈)으로 줄여서 나타내요.", "키가 140cm, 141cm, 143cm, 144cm로 변했다면 0cm부터 139cm까지는 쓸 일이 없어요. 물결선을 넣고 139cm부터 눈금을 그리면 눈금 한 칸을 1cm로 크게 그릴 수 있어서 변화가 잘 보여요."], "example": "세로 눈금: 0 ≈ 139, 140, 141, 142, 143, 144 (cm)", "figure": "세로축 아래쪽에 물결선을 넣고 139cm부터 눈금을 그린 키 변화 꺾은선그래프"}, {"heading": "이렇게 그려요: 꺾은선그래프 그리기", "paras": ["① 가로와 세로에 무엇을 나타낼지 정해요. ② 가장 큰 값까지 나타낼 수 있게 세로 눈금 한 칸의 크기를 정하고, 필요하면 물결선을 넣어요. ③ 가로 눈금과 세로 눈금이 만나는 자리에 점을 찍어요. ④ 점들을 차례로 선분으로 이어요. ⑤ 알맞은 제목을 붙여요.", "막대그래프는 여러 항목의 크기를 비교할 때 편리하고, 꺾은선그래프는 시간에 따른 변화를 볼 때 편리해요. 반 친구들이 좋아하는 과일은 막대그래프로, 한 달 동안 강낭콩의 키는 꺾은선그래프로 나타내면 좋아요."], "example": "좋아하는 과일별 학생 수 → 막대그래프, 날짜별 강낭콩 키 → 꺾은선그래프", "figure": "왼쪽에는 과일별 막대그래프, 오른쪽에는 날짜별 강낭콩 키 꺾은선그래프를 나란히 놓은 그림"}], "keywords": [{"word": "꺾은선그래프", "meaning": "수량을 점으로 찍고 그 점들을 선분으로 이어 그린 그래프"}, {"word": "물결선", "meaning": "그래프에서 필요 없는 부분을 줄여 나타낼 때 쓰는 ≈ 모양의 선"}, {"word": "눈금 한 칸", "meaning": "세로 눈금 한 칸이 나타내는 크기, 자료에 맞게 정해요"}, {"word": "변화", "meaning": "시간이 지나면서 양이 늘어나거나 줄어드는 것"}, {"word": "막대그래프", "meaning": "항목별 수량을 막대 길이로 나타낸 그래프, 크기 비교에 편리해요"}], "expressions": [], "quiz": [{"q": "꺾은선그래프로 나타내기에 가장 알맞은 것은 무엇일까요?", "choices": ["반 친구들이 좋아하는 운동", "우리 반 학생들의 혈액형", "한 달 동안 강낭콩 키의 변화", "마을별 학생 수"], "answer": 2, "explain": "시간에 따라 변하는 양은 꺾은선그래프로 나타내면 변화가 잘 보여요."}, {"q": "꺾은선그래프에서 선분이 오른쪽 아래로 내려가면 무엇을 뜻할까요?", "choices": ["양이 줄어들었어요", "양이 늘어났어요", "양이 변하지 않았어요", "자료가 틀렸어요"], "answer": 0, "explain": "오른쪽 아래로 내려가는 선분은 시간이 지나며 양이 줄어든 것을 나타내요."}, {"q": "기온이 오전 9시 12°C, 10시 15°C, 11시 19°C, 낮 12시 22°C였어요. 기온이 가장 많이 오른 때는 언제일까요?", "choices": ["오전 9시~10시", "낮 12시~오후 1시", "오전 11시~낮 12시", "오전 10시~11시"], "answer": 3, "explain": "3°C, 4°C, 3°C 올랐으니 오전 10시~11시에 4°C로 가장 많이 올랐어요."}, {"q": "물결선을 쓰는 까닭으로 알맞은 것은 무엇일까요?", "choices": ["그래프를 예쁘게 꾸미려고", "필요 없는 부분을 줄여 변화를 잘 보이게 하려고", "점을 찍지 않으려고", "가로 눈금을 없애려고"], "answer": 1, "explain": "물결선으로 쓰지 않는 아랫부분을 줄이면 눈금 한 칸을 크게 할 수 있어 변화가 잘 보여요."}, {"q": "오후 1시에 20°C, 오후 2시에 24°C였어요. 오후 1시 30분의 기온은 약 몇 °C였다고 어림할 수 있을까요?", "choices": ["약 20°C", "약 21°C", "약 22°C", "약 26°C"], "answer": 2, "explain": "20°C와 24°C의 가운데쯤이므로 약 22°C로 어림해요."}], "summary": ["꺾은선그래프는 수량을 점으로 찍고 선분으로 이어, 시간에 따른 변화를 한눈에 보여 줘요.", "선분이 많이 기울수록 변화가 크고, 필요 없는 부분은 물결선으로 줄여 나타내요.", "크기 비교는 막대그래프, 시간에 따른 변화는 꺾은선그래프가 편리해요."], "parent_tip": "아이들은 세로 눈금 한 칸이 1이 아닐 때(2, 5, 0.5 등) 값을 잘못 읽는 경우가 많습니다. 그래프를 읽기 전에 '눈금 한 칸은 얼마일까?'를 먼저 묻고, 물결선이 있으면 어디부터 시작하는지 확인하게 해 주세요. 아이와 함께 며칠 동안 아침·저녁 기온이나 화분의 키를 재어 직접 꺾은선그래프로 그려 보면 가장 오래 기억합니다."}$j$::jsonb,410) on conflict (slug) do update set grade=4,semester=excluded.semester,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,grade,semester,subject,name,sort_order,lesson_slug) select '3~4',4,2,'수학','꺾은선그래프',410,'m4-11' where not exists (select 1 from public.topics where lesson_slug='m4-11');
